package reviews

import (
	"fmt"
	"strings"
)

// The brief a reviewer conversation starts with. It is generated by the
// Runner from what it already records (the source conversation's first
// prompt, the workspace's latest plan, the scope's diff and files, the
// `lazybox run` reports) into an editable template (Settings → Review). The
// reporting instructions are not the person's to drop: a template without
// {{report}} still gets them at its end, or no finding would ever arrive.

// DefaultTemplate is the built-in brief. Placeholders: {{reviewer}},
// {{author}}, {{conversation}}, {{goal}}, {{plan}}, {{scope}}, {{diff}},
// {{files}}, {{evidence}}, {{report}}.
const DefaultTemplate = `You are an independent reviewer ({{reviewer}}) of work {{author}} did in this workspace, in the conversation “{{conversation}}”. Review it; do not change anything.

## The goal of the work

{{goal}}

{{plan}}

## What to review: {{scope}}

{{diff}}

Files in scope:
{{files}}

## Evidence so far

{{evidence}}

## What to look for

Correctness bugs, regressions, missing or wrong tests, security and data-loss risks, and anything that does not do what the goal asks. Read the code around the change, not only the diff. Prefer a few well-evidenced findings over many speculative ones, and quote the code you mean. Style is a nit unless it hurts understanding.

{{report}}`

// ReportInstructions is the {{report}} section: how findings reach Lazybox.
const ReportInstructions = `## How to report

File one finding at a time with the Runner’s review finding tool (lazybox_review_finding or mcp__lazybox__review_finding). Pass file, startLine, optional endLine, severity, title and body. Wait for the saved finding ID before saying it was filed. This tool does not spawn a command or require shell network access.

If the tool is unavailable, use the Lazybox CLI:

    lazybox review add --file <repository>/<path> --line <N>[-<M>] --severity blocker|major|minor|nit --title "<one line>" --body "<what is wrong, why it matters, what to do>"

- --file is relative to the workspace root (api/src/handler.go); --line is the line as the file is now; a range such as 12-18 is fine.
- blocker: wrong or unsafe to merge · major: should be fixed before merging · minor: worth fixing · nit: taste.
- Filing the same file, line and title again (or the same --key) updates that finding instead of adding another. ` + "`lazybox review list`" + ` shows what you filed.
- If filing cannot be confirmed, include each finding’s file, lines, severity, title and body in your reply and mark it as unfiled.
- To ask the author about its intent, run ` + "`lazybox ask author \"<question>\"`" + `; its reply comes back to you. Ask only what the code cannot tell you.

You are read-only: never edit files, commit, push or open pull requests. Route implementation and merging back to the author conversation. Inspect files and diffs using the provider’s native read-only tools. Use the author’s recorded test evidence and report any checks you could not verify.

When you are done, end your turn with a short summary: what you checked, your findings by severity, and what you could not verify.`

// BriefInput is what a brief is made of.
type BriefInput struct {
	Guidance                       string
	Reviewer, Author, Conversation string
	// Goal is the source conversation's first prompt; Plan the workspace's
	// latest plan artifact, if any.
	Goal, Plan string
	// Scope names what is reviewed; Diff says how to read it.
	Scope, Diff string
	Files       []string
	Evidence    []string
	// Template is the person's; "" is DefaultTemplate.
	Template string
	// Focus is what the person asked the reviewer to look at in particular
	// (`/review <focus>`): the {{focus}} section, else one before {{report}}.
	Focus string
}

// FocusLimit bounds the focus a person gives a review.
const FocusLimit = TemplateLimit

const (
	goalLimit  = 6 << 10
	planLimit  = 8 << 10
	filesLimit = 200
	runsShown  = 20
)

func clip(text string, limit int) string {
	text = strings.TrimSpace(text)
	if len(text) <= limit {
		return text
	}
	cut := strings.LastIndexAny(text[:limit], "\n ")
	if cut < limit/2 {
		cut = limit
	}
	return strings.TrimSpace(text[:cut]) + "\n[…shortened; the full text is in the conversation]"
}

// quote indents text as a Markdown quote.
func quote(text string) string {
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		lines[i] = strings.TrimRight("> "+line, " ")
	}
	return strings.Join(lines, "\n")
}

// Brief renders the reviewer's first message.
func Brief(in BriefInput) string {
	template := strings.TrimSpace(in.Template)
	if template == "" {
		template = DefaultTemplate
	}
	if in.Guidance != "" && !strings.Contains(template, "{{diff}}") {
		template += "\n\n{{diff}}"
	}
	if !strings.Contains(template, "{{report}}") {
		template += "\n\n{{report}}"
	}
	focus := ""
	if f := clip(in.Focus, FocusLimit); f != "" {
		focus = "## What the person asked you to focus on\n\n" + quote(f) + "\n\nLook at this first; still report anything else you find."
		if !strings.Contains(template, "{{focus}}") {
			template = strings.Replace(template, "{{report}}", "{{focus}}\n\n{{report}}", 1)
		}
	}
	goal := "(The conversation has no recorded first message.)"
	if g := clip(in.Goal, goalLimit); g != "" {
		goal = "Its first message:\n\n" + quote(g)
	}
	plan := ""
	if p := clip(in.Plan, planLimit); p != "" {
		plan = "The latest plan in this workspace:\n\n" + quote(p)
	}
	files := "- (no changed files found; read the diff above)"
	if n := len(in.Files); n > 0 {
		shown := in.Files
		if n > filesLimit {
			shown = shown[:filesLimit]
		}
		files = "- " + strings.Join(shown, "\n- ")
		if n > filesLimit {
			files += fmt.Sprintf("\n- …and %d more", n-filesLimit)
		}
	}
	evidence := "No `lazybox run` results were recorded in that conversation. Report the missing test evidence."
	if n := len(in.Evidence); n > 0 {
		shown := in.Evidence
		if n > runsShown {
			shown = shown[n-runsShown:]
		}
		evidence = "Commands the author ran with `lazybox run`, newest last:\n\n- " + strings.Join(shown, "\n- ")
	}
	replacer := strings.NewReplacer(
		"{{reviewer}}", in.Reviewer, "{{author}}", firstNonEmpty(in.Author, "another agent"), "{{conversation}}", firstNonEmpty(in.Conversation, "untitled"),
		"{{goal}}", goal, "{{plan}}", plan, "{{scope}}", in.Scope, "{{diff}}", strings.TrimSpace(in.Diff),
		"{{files}}", files, "{{evidence}}", evidence, "{{focus}}", focus, "{{report}}", ReportInstructions)
	out := replacer.Replace(template)
	if in.Guidance != "" {
		out = in.Guidance + "\n\n" + out
	}
	// An empty section leaves blank lines behind; keep at most one.
	for strings.Contains(out, "\n\n\n") {
		out = strings.ReplaceAll(out, "\n\n\n", "\n\n")
	}
	return strings.TrimSpace(out)
}

func firstNonEmpty(values ...string) string {
	for _, v := range values {
		if strings.TrimSpace(v) != "" {
			return v
		}
	}
	return ""
}

// TemplateLimit bounds a person's template.
const TemplateLimit = 32 << 10
